import math
import mmh3
import json
from typing import List, Set, Dict, Any

class HyperLogLogDigest:
    """
    Memory-bounded Gossip Digest Compactor using HyperLogLog probabilistic cardinality estimator.
    Maintains strict sub-linear space complexity (<1KB per peer state digest) while bounding estimation error.
    """
    def __init__(self, precision: int = 12):
        if not (4 <= precision <= 16):
            raise ValueError("Precision must be between 4 and 16")
        self.precision = precision
        self.m = 1 << precision
        self.registers = [0] * self.m
        self._alpha = self._get_alpha()

    def _get_alpha(self) -> float:
        if self.m == 16:
            return 0.673
        elif self.m == 32:
            return 0.697
        elif self.m == 64:
            return 0.709
        else:
            return 0.7213 / (1.0 + 1.079 / self.m)

    def _hash(self, item: str) -> int:
        return mmh3.hash64(str(item), seed=42)[0] & 0xFFFFFFFFFFFFFFFF

    def add(self, item: str) -> None:
        x = self._hash(item)
        j = x >> (64 - self.precision)
        w = x & ((1 << (64 - self.precision)) - 1)
        rho = self._rho(w, 64 - self.precision)
        if rho > self.registers[j]:
            self.registers[j] = rho

    def _rho(self, w: int, max_bits: int) -> int:
        if w == 0:
            return max_bits + 1
        return max_bits - w.bit_length() + 1

    def estimate_cardinality(self) -> float:
        Z = sum(2.0 ** (-r) for r in self.registers)
        raw_estimate = self._alpha * (self.m ** 2) / Z

        if raw_estimate <= 2.5 * self.m:
            V = self.registers.count(0)
            if V > 0:
                return self.m * math.log(self.m / V)

        # Correct for large range if necessary
        two_to_32 = 4294967296.0
        if raw_estimate > (two_to_32 / 30.0):
            return -two_to_32 * math.log(1.0 - raw_estimate / two_to_32)

        return raw_estimate

    def merge(self, other: 'HyperLogLogDigest') -> 'HyperLogLogDigest':
        if self.precision != other.precision:
            raise ValueError("Cannot merge HyperLogLog digests with different precisions")
        merged = HyperLogLogDigest(precision=self.precision)
        merged.registers = [max(a, b) for a, b in zip(self.registers, other.registers)]
        return merged

    def serialize(self) -> str:
        return json.dumps({
            "precision": self.precision,
            "registers": self.registers
        })

    @classmethod
    def deserialize(cls, data_str: str) -> 'HyperLogLogDigest':
        data = json.loads(data_str)
        obj = cls(precision=data["precision"])
        obj.registers = data["registers"]
        return obj

from typing import List, Dict, Any
from gossipmesh.p2p.digest import HyperLogLogDigest

class GossipDigestCompactor:
    """
    Compactor for anti-entropy sync payloads using HLL digests.
    Maintains state sync payload sizes under high message volumes.
    """
    def __init__(self, precision: int = 12):
        self.precision = precision

    def compact_state(self, message_ids: List[str]) -> HyperLogLogDigest:
        digest = HyperLogLogDigest(precision=self.precision)
        for msg_id in message_ids:
            digest.add(msg_id)
        return digest

    def compute_diff(self, local_digest: HyperLogLogDigest, remote_digest: HyperLogLogDigest) -> float:
        merged = local_digest.merge(remote_digest)
        est_local = local_digest.estimate_cardinality()
        est_merged = merged.estimate_cardinality()
        return abs(est_merged - est_local)

    def serialize_digest(self, digest: HyperLogLogDigest) -> str:
        return digest.serialize()

    def deserialize_digest(self, data_str: str) -> HyperLogLogDigest:
        return HyperLogLogDigest.deserialize(data_str)
